begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('08000000-0000-4000-8000-000000000001','ops-admin@example.test',now()),('08000000-0000-4000-8000-000000000002','ops-member@example.test',now());
insert into auth.sessions(id,user_id,created_at,updated_at) values('18000000-0000-4000-8000-000000000001','08000000-0000-4000-8000-000000000001',now(),now()),('18000000-0000-4000-8000-000000000002','08000000-0000-4000-8000-000000000002',now(),now());
insert into profiles(id,username,display_name,role,policy_version,policy_accepted_at)values('08000000-0000-4000-8000-000000000001','ops_admin','Admin','admin','2026-11-01',now()),('08000000-0000-4000-8000-000000000002','ops_member','Member','member','2026-11-01',now());
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values('98000000-0000-4000-8000-000000000001','08000000-0000-4000-8000-000000000002','totp','verified',now(),now());
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"08000000-0000-4000-8000-000000000002","session_id":"18000000-0000-4000-8000-000000000002","aal":"aal1"}',true);
select ok(not is_approved(),'enrolled MFA requires AAL2 at the database boundary');
select set_config('request.jwt.claims','{"sub":"08000000-0000-4000-8000-000000000002","session_id":"18000000-0000-4000-8000-000000000002","aal":"aal2"}',true);
select ok(is_approved(),'AAL2 restores enrolled member access');
reset role;
insert into classes(id,name,created_by)values('28000000-0000-4000-8000-000000000001','Operations','08000000-0000-4000-8000-000000000002');
insert into quizzes(id,class_id,title,created_by)values('48000000-0000-4000-8000-000000000001','28000000-0000-4000-8000-000000000001','Practice','08000000-0000-4000-8000-000000000002');
insert into quiz_versions(id,quiz_id,version,kind,status,content,created_by)values('58000000-0000-4000-8000-000000000001','48000000-0000-4000-8000-000000000001',1,'manual','published','{"format_version":1,"questions":[{"id":"q1","type":"true_false","prompt":"A?","points":1,"answer":true}]}','08000000-0000-4000-8000-000000000002');
update quizzes set published_version_id='58000000-0000-4000-8000-000000000001';
set local role authenticated;
select record_attempt(gen_random_uuid(),'58000000-0000-4000-8000-000000000001',1,1,'{"responses":{"q1":true},"question_ids":["q1"]}',now()-interval '1 minute') from generate_series(1,29);
select is((select count(*) from attempts where not summary),29::bigint,'full attempt retention accepts limit minus one');
select record_attempt(gen_random_uuid(),'58000000-0000-4000-8000-000000000001',1,1,'{"responses":{"q1":true},"question_ids":["q1"]}',now()-interval '1 minute');
select is((select count(*) from attempts where not summary),30::bigint,'full attempt retention keeps exact limit');
select record_attempt(gen_random_uuid(),'58000000-0000-4000-8000-000000000001',1,1,'{"responses":{"q1":true},"question_ids":["q1"]}',now()-interval '1 minute');
select is((select count(*) from attempts where not summary),30::bigint,'newer attempt summarizes excess detail');
select is((select count(*) from attempts where summary and answers is null and score=1),1::bigint,'older score survives summary retention');
reset role;
insert into files(id,path,name,mime,size,purpose,state,ready_at,created_by) values('68000000-0000-4000-8000-000000000001','ready/ops.html','ops.html','text/html',10,'html_quiz','ready',now(),'08000000-0000-4000-8000-000000000002');
insert into quiz_versions(id,quiz_id,version,kind,content,html_file_id,created_by) values('58000000-0000-4000-8000-000000000002','48000000-0000-4000-8000-000000000001',2,'html','{"path":"ready/ops.html"}','68000000-0000-4000-8000-000000000001','08000000-0000-4000-8000-000000000002'),('58000000-0000-4000-8000-000000000003','48000000-0000-4000-8000-000000000001',3,'html','{"path":"ready/ops.html"}','68000000-0000-4000-8000-000000000001','08000000-0000-4000-8000-000000000002');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"08000000-0000-4000-8000-000000000002","session_id":"18000000-0000-4000-8000-000000000002","aal":"aal2"}',true);
select is((select count(*) from files where name='ops.html'),1::bigint,'author can read own draft HTML metadata');
reset role;
insert into auth.users(id,email,email_confirmed_at)values('08000000-0000-4000-8000-000000000003','ops-other@example.test',now());
insert into auth.sessions(id,user_id,created_at,updated_at)values('18000000-0000-4000-8000-000000000003','08000000-0000-4000-8000-000000000003',now(),now());
insert into profiles(id,username,display_name,policy_version,policy_accepted_at)values('08000000-0000-4000-8000-000000000003','ops_other','Other','2026-11-01',now());
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"08000000-0000-4000-8000-000000000003","session_id":"18000000-0000-4000-8000-000000000003","aal":"aal1"}',true);
select is((select count(*) from files where name='ops.html'),0::bigint,'another member cannot read draft HTML metadata');
reset role;
update quiz_versions set status='published' where version=2;
set local role authenticated;
select is((select count(*) from files where name='ops.html'),1::bigint,'published HTML metadata becomes available to approved members');
reset role;
delete from quiz_versions where version=2;
select is((select state from files where name='ops.html'),'ready','shared HTML asset survives while another version references it');
delete from quiz_versions where version=3;
select is((select state from files where name='ops.html'),'deleting','last reference removal schedules HTML bytes for deletion');
select ok(exists(select 1 from notifications where entity_id='58000000-0000-4000-8000-000000000003'),'HTML deletion emits cache eviction notification');
insert into files(path,name,mime,size,purpose,state,ready_at)values('ready/unused.html','unused.html','text/html',10,'html_quiz','ready',now());
set local role authenticated;
select is((select count(*) from unused_html_assets()),0::bigint,'member cannot list administrator orphan assets');
select set_config('request.jwt.claims','{"sub":"08000000-0000-4000-8000-000000000001","session_id":"18000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select is((select count(*) from unused_html_assets()),1::bigint,'admin can reclaim an unused HTML upload');
reset role;
insert into chat_messages(user_id,body)values('08000000-0000-4000-8000-000000000002','older'),('08000000-0000-4000-8000-000000000002','boundary'),('08000000-0000-4000-8000-000000000002','newer');
update chat_messages set created_at=now()-interval '90 days'+case body when 'older' then interval '-1 second' when 'newer' then interval '1 second' else interval '0' end;
insert into activity_log(action,created_at)values('retention.older',now()-interval '60 days 1 second'),('retention.boundary',now()-interval '60 days');
insert into notifications(user_id,kind,title,created_at)values('08000000-0000-4000-8000-000000000002','role_changed','retention older',now()-interval '30 days 1 second'),('08000000-0000-4000-8000-000000000002','role_changed','retention boundary',now()-interval '30 days');
insert into invitations(email,created_at,expires_at,accepted_at)values('expired-record@example.test',now()-interval '100 days',now()-interval '90 days',now()-interval '61 days');
select lives_ok('select apply_retention()','retention job runs successfully');
select is((select count(*) from chat_messages),2::bigint,'chat older than retention removed, boundary/newer preserved');
select is((select count(*) from activity_log where action like 'retention.%'),1::bigint,'activity retention respects boundary');
select is((select count(*) from notifications where title like 'retention %'),1::bigint,'notification retention respects boundary');
select is((select count(*) from invitations where email='expired-record@example.test'),0::bigint,'accepted invitations do not retain email indefinitely');
insert into invitations(email,auth_user_id,expires_at,accepted_at)values('ops-member@example.test','08000000-0000-4000-8000-000000000002',now()+interval '1 day',now());
select lives_ok($$select prepare_account_deletion('08000000-0000-4000-8000-000000000001','08000000-0000-4000-8000-000000000002',false)$$,'administrator can prepare member deletion');
select is((select count(*) from invitations where auth_user_id='08000000-0000-4000-8000-000000000002'),0::bigint,'deletion removes bound invitation email');
select lives_ok($$delete from auth.users where id='08000000-0000-4000-8000-000000000002'$$,'Auth deletion completes for non-admin');
select is((select created_by from classes where id='28000000-0000-4000-8000-000000000001'),null::uuid,'surviving shared content is anonymized');
select is((select count(*) from attempts),0::bigint,'private attempts cascade on account deletion');
select is((select count(*) from chat_messages),0::bigint,'own chat messages cascade on deletion');
select is((select count(*) from quiz_versions where status='published'),1::bigint,'published contribution survives author leaving');
select * from finish();
rollback;
